import { deepClone } from "../../commonHelpers/utils";
import { createDisplayingElements } from "./createDisplayingElements";
export const handleShortnessOfRequiredWidth = (children, widthProps, displayingElements) => {
    let displayingElementsClone = deepClone(displayingElements);
    if (widthProps.requiredWidth < widthProps.width) {
        for (let i = 0; i <= children.length - 1 && widthProps.requiredWidth <= widthProps.width; i++) {
            if (children[i].classList.contains("zen-toolbar__item--more")) {
                continue;
            }
            const additionalElementsInd = [];
            children[i].childNodes.forEach((el, ind) => {
                if (el.classList.contains("zen-toolbar__item-priority")) {
                    return;
                }
                additionalElementsInd.push(ind);
            });
            for (let j = 0; j < additionalElementsInd.length; j++) {
                displayingElementsClone = createDisplayingElements(i, children, displayingElementsClone, widthProps)(additionalElementsInd[j]);
            }
        }
    }
    return displayingElementsClone;
};
